<h2>Convert paper basis weight and GSM</h2><p class="lead">Convert U.S. basis weight in pounds per ream to grammage only when the basic sheet size and ream count are known.</p><div class="notice">TAPPI defines grammage as mass per unit area and basis weight as pounds for a stated ream/basic size. Common basic sizes include 17×22 bond, 25×38 text/book and 20×26 cover, but verify your grade.</div><div class="form-grid"><div class="field"><label for="mode">Conversion direction</label><select id="mode"><option value="lb2gsm" selected>Basis weight (lb) → GSM</option><option value="gsm2lb">GSM → basis weight (lb)</option></select></div><div class="field"><label for="value">Weight value</label><input id="value" type="number" value="80" min="0.001" step="any"></div><div class="field"><label for="bw">Basic sheet width (inches)</label><input id="bw" type="number" value="25" min="0.001" step="any"></div><div class="field"><label for="bh">Basic sheet height (inches)</label><input id="bh" type="number" value="38" min="0.001" step="any"></div><div class="field"><label for="ream">Sheets per ream</label><input id="ream" type="number" value="500" min="1" step="1"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Grammage</span><strong id="gsm">—</strong></div><div class="metric"><span>Basis weight</span><strong id="lb">—</strong></div><div class="metric"><span>Basic sheet area</span><strong id="area">—</strong></div><div class="metric"><span>Mass of one basic sheet</span><strong id="mass">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('gsm').textContent='—';$('lb').textContent='—';$('area').textContent='—';$('mass').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const mode=$('mode').value,v=num('value'),w=num('bw'),h=num('bh'),r=num('ream');if(!(v>0&&w>0&&h>0&&r>0))throw 0;const areaIn=w*h,areaM=areaIn*0.00064516;let gsm,lb;if(mode==='lb2gsm'){lb=v;gsm=(lb*453.59237)/(r*areaM)}else{gsm=v;lb=gsm*r*areaM/453.59237}$('gsm').textContent=fmt(gsm,2)+' g/m²';$('lb').textContent=fmt(lb,2)+' lb/ream';$('area').textContent=fmt(areaIn,2)+' in²';$('mass').textContent=fmt(gsm*areaM,2)+' g';$('note').textContent='Basis weight is grade-specific because the basic sheet size differs. There is no universal “80 lb = one GSM” conversion without the basis size and ream count.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
